{
  "name": "BioLink SaaS - Multi-tenant Link-in-Bio Platform",
  "description": "A complete, high-performance SaaS platform for creating personalized link-in-bio pages with dynamic user directories, real-time analytics, and a powerful dashboard."
}

export interface User {
  id: string;
  name: string;
  email: string;
  username: string;
  createdAt: string;
}

export interface BioPage {
  id: string;
  userId: string;
  title: string;
  description: string;
  profileImageUrl: string;
  themeColor: string;
  fontFamily: string;
  isActive: boolean;
}

export interface BioLink {
  id: string;
  bioPageId: string;
  title: string;
  url: string;
  icon?: string;
  position: number;
  clicks: number;
  isActive: boolean;
}

export interface AnalyticsRecord {
  id: string;
  linkId: string;
  ipAddress: string;
  userAgent: string;
  createdAt: string;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
}

import React from 'react';

export const APP_NAME = "BioLink";

export const THEMES = [
  { id: 'classic', color: '#000000', label: 'Classic Black' },
  { id: 'ocean', color: '#0ea5e9', label: 'Ocean Blue' },
  { id: 'sunset', color: '#f43f5e', label: 'Sunset Red' },
  { id: 'emerald', color: '#10b981', label: 'Emerald Green' },
  { id: 'royal', color: '#6366f1', label: 'Royal Indigo' },
];

export const FONTS = [
  { id: 'sans', family: 'Inter, sans-serif', label: 'Modern Sans' },
  { id: 'serif', family: 'Georgia, serif', label: 'Elegant Serif' },
  { id: 'mono', family: 'monospace', label: 'Clean Mono' },
];

import { User, BioPage, BioLink } from '../types';

// In a real app, this would be Prisma on the backend.
// We simulate the multi-tenant architecture here using localStorage.

const STORAGE_KEYS = {
  USERS: 'biolink_users',
  PAGES: 'biolink_pages',
  LINKS: 'biolink_links',
  ANALYTICS: 'biolink_analytics'
};

export const db = {
  getUsers: (): User[] => JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]'),
  saveUser: (user: User) => {
    const users = db.getUsers();
    localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify([...users, user]));
  },
  findUserByUsername: (username: string) => db.getUsers().find(u => u.username === username),

  getPages: (): BioPage[] => JSON.parse(localStorage.getItem(STORAGE_KEYS.PAGES) || '[]'),
  getPageByUsername: (username: string) => {
    const user = db.findUserByUsername(username);
    if (!user) return null;
    return db.getPages().find(p => p.userId === user.id);
  },
  savePage: (page: BioPage) => {
    const pages = db.getPages().filter(p => p.id !== page.id);
    localStorage.setItem(STORAGE_KEYS.PAGES, JSON.stringify([...pages, page]));
  },

  getLinks: (pageId: string): BioLink[] => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]');
    return links.filter((l: BioLink) => l.bioPageId === pageId).sort((a: any, b: any) => a.position - b.position);
  },
  saveLink: (link: BioLink) => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]').filter((l: any) => l.id !== link.id);
    localStorage.setItem(STORAGE_KEYS.LINKS, JSON.stringify([...links, link]));
  },
  deleteLink: (id: string) => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]').filter((l: any) => l.id !== id);
    localStorage.setItem(STORAGE_KEYS.LINKS, JSON.stringify(links));
  }
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useParams } from 'react-router-dom';
import Login from './pages/Login';
import Register from './pages/Register';
import DashboardLayout from './components/DashboardLayout';
import DashboardHome from './pages/DashboardHome';
import LinksManager from './pages/LinksManager';
import DesignCustomizer from './pages/DesignCustomizer';
import Analytics from './pages/Analytics';
import PublicBio from './pages/PublicBio';
import { AuthState, User } from './types';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('auth');
    return saved ? JSON.parse(saved) : { user: null, token: null, isAuthenticated: false };
  });

  useEffect(() => {
    localStorage.setItem('auth', JSON.stringify(auth));
  }, [auth]);

  const login = (user: User, token: string) => {
    setAuth({ user, token, isAuthenticated: true });
  };

  const logout = () => {
    setAuth({ user: null, token: null, isAuthenticated: false });
  };

  return (
    <HashRouter>
      <Routes>
        {/* Public Landing (Redirect to login or dashboard) */}
        <Route path="/" element={auth.isAuthenticated ? <Navigate to="/dashboard" /> : <Navigate to="/login" />} />

        {/* Auth Routes */}
        <Route path="/login" element={<Login onLogin={login} />} />
        <Route path="/register" element={<Register onRegister={login} />} />

        {/* Dashboard Routes (Protected) */}
        <Route path="/dashboard" element={auth.isAuthenticated ? <DashboardLayout user={auth.user!} onLogout={logout} /> : <Navigate to="/login" />}>
          <Route index element={<DashboardHome user={auth.user!} />} />
          <Route path="links" element={<LinksManager user={auth.user!} />} />
          <Route path="design" element={<DesignCustomizer user={auth.user!} />} />
          <Route path="analytics" element={<Analytics user={auth.user!} />} />
        </Route>

        {/* Dynamic Public Username Route: /:username */}
        <Route path="/:username" element={<PublicBio />} />

        {/* Fallback */}
        <Route path="*" element={<div className="p-10 text-center">404 - Not Found</div>} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React from 'react';
