};

export default DashboardLayout;

import React from 'react';
import { User } from '../types';
import { db } from '../services/db';
import { ArrowUpRight, MousePointer2, Users, Link as LinkIcon } from 'lucide-react';

interface Props {
  user: User;
}

const DashboardHome: React.FC<Props> = ({ user }) => {
  const page = db.getPageByUsername(user.username);
  const links = page ? db.getLinks(page.id) : [];
  const totalClicks = links.reduce((acc, curr) => acc + curr.clicks, 0);

  const stats = [
    { label: 'Total Clicks', value: totalClicks, icon: <MousePointer2 className="text-blue-600" />, trend: '+12%' },
    { label: 'Active Links', value: links.filter(l => l.isActive).length, icon: <LinkIcon className="text-green-600" />, trend: 'Stable' },
    { label: 'Page Views', value: totalClicks * 1.5, icon: <Users className="text-purple-600" />, trend: '+5%' },
  ];

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-gray-900">Welcome back, {user.name}!</h1>
        <p className="text-gray-500 mt-1">Here's what's happening with your BioLink page.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((stat) => (
          <div key={stat.label} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <div className="flex justify-between items-start mb-4">
              <div className="p-3 bg-gray-50 rounded-xl">{stat.icon}</div>
              <span className="text-xs font-bold text-green-500 bg-green-50 px-2 py-1 rounded-full">{stat.trend}</span>
            </div>
            <p className="text-gray-500 text-sm font-medium">{stat.label}</p>
            <h3 className="text-2xl font-bold mt-1">{stat.value}</h3>
          </div>
        ))}
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm">
        <div className="p-6 border-b border-gray-100 flex justify-between items-center">
          <h3 className="font-bold text-gray-900">Top Performing Links</h3>
          <button className="text-blue-600 text-sm font-semibold hover:underline">View All</button>
        </div>
        <div className="divide-y divide-gray-50">
          {links.length > 0 ? (
            links.sort((a,b) => b.clicks - a.clicks).slice(0, 5).map(link => (
              <div key={link.id} className="p-4 flex items-center justify-between hover:bg-gray-50 transition-colors">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center">
                    <LinkIcon size={18} className="text-gray-400" />
                  </div>
                  <div>
                    <p className="font-semibold text-gray-900">{link.title}</p>
                    <p className="text-xs text-gray-400 truncate max-w-[200px]">{link.url}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="font-bold text-gray-900">{link.clicks}</p>
                  <p className="text-xs text-gray-400 uppercase tracking-wider">Clicks</p>
                </div>
              </div>
            ))
          ) : (
            <div className="p-12 text-center text-gray-400">
              No links created yet. Start by adding one in the Links tab!
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DashboardHome;

import React, { useState, useEffect } from 'react';
import { User, BioLink } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, ExternalLink, GripVertical, ToggleLeft, ToggleRight } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLink, setNewLink] = useState({ title: '', url: '' });
  const [isAdding, setIsAdding] = useState(false);

  const page = db.getPageByUsername(user.username);

  useEffect(() => {
    if (page) {
      setLinks(db.getLinks(page.id));
    }
  }, [page?.id]);

  const handleAddLink = () => {
    if (!page || !newLink.title || !newLink.url) return;

    const link: BioLink = {
      id: Math.random().toString(36).substr(2, 9),
      bioPageId: page.id,
      title: newLink.title,
      url: newLink.url.startsWith('http') ? newLink.url : `https://${newLink.url}`,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    db.saveLink(link);
    setLinks([...links, link]);
    setNewLink({ title: '', url: '' });
    setIsAdding(false);
  };

  const toggleLink = (id: string) => {
    const updated = links.map(l => {
      if (l.id === id) {
        const newL = { ...l, isActive: !l.isActive };
        db.saveLink(newL);
        return newL;
      }
      return l;
    });
    setLinks(updated);
  };

  const deleteLink = (id: string) => {
    db.deleteLink(id);
    setLinks(links.filter(l => l.id !== id));
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Manage Links</h1>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-md active:scale-95"
        >
          <Plus size={20} /> Add New Link
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl shadow-sm border-2 border-blue-100 animate-in slide-in-from-top duration-300">
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Title</label>
              <input 
                type="text" 
                placeholder="e.g. My Website"
                value={newLink.title}
                onChange={e => setNewLink({ ...newLink, title: e.target.value })}
                className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">URL</label>
              <input 
                type="text" 
                placeholder="https://example.com"
                value={newLink.url}
                onChange={e => setNewLink({ ...newLink, url: e.target.value })}
                className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>
            <div className="flex gap-3 justify-end pt-2">
              <button onClick={() => setIsAdding(false)} className="px-4 py-2 text-gray-500 font-medium">Cancel</button>
              <button onClick={handleAddLink} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">Save Link</button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {links.map((link) => (
          <div key={link.id} className="bg-white p-4 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-4 group">
            <div className="text-gray-300 cursor-grab active:cursor-grabbing">
              <GripVertical size={20} />
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h4 className="font-bold text-gray-900">{link.title}</h4>
                {!link.isActive && <span className="text-[10px] bg-gray-100 text-gray-500 px-1.5 py-0.5 rounded font-bold uppercase tracking-wider">Draft</span>}
              </div>
              <p className="text-sm text-gray-400 truncate max-w-md">{link.url}</p>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={() => toggleLink(link.id)}
                className={`p-2 rounded-lg transition-colors ${link.isActive ? 'text-green-500 hover:bg-green-50' : 'text-gray-300 hover:bg-gray-50'}`}
              >
                {link.isActive ? <ToggleRight size={28} /> : <ToggleLeft size={28} />}
              </button>
              <button 
                onClick={() => deleteLink(link.id)}
                className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
              >
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
        {links.length === 0 && !isAdding && (
          <div className="bg-dashed border-2 border-dashed border-gray-200 rounded-3xl p-12 text-center">
            <p className="text-gray-400 font-medium mb-4">Your link list is empty</p>
            <button onClick={() => setIsAdding(true)} className="text-blue-600 font-bold">Add your first link →</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default LinksManager;

import React, { useState, useEffect } from 'react';
import { User, BioPage } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Check, Image as ImageIcon } from 'lucide-react';

interface Props {
  user: User;
}

const DesignCustomizer: React.FC<Props> = ({ user }) => {
  const [page, setPage] = useState<BioPage | null>(null);

  useEffect(() => {
    const existing = db.getPageByUsername(user.username);
    if (existing) {
      setPage(existing);
    } else {
      // Create default
      const newPage: BioPage = {
        id: Math.random().toString(36).substr(2, 9),
        userId: user.id,
        title: user.name,
        description: `Welcome to my profile!`,
        profileImageUrl: `https://picsum.photos/seed/${user.username}/200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true
      };
      db.savePage(newPage);
      setPage(newPage);
    }
  }, [user]);

  const updatePage = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  if (!page) return null;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
      <div className="space-y-8">
        <div>
          <h1 className="text-2xl font-bold">Design Your Page</h1>
          <p className="text-gray-500">Customize the look and feel of your BioLink.</p>
        </div>

        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-6">
          <div>
            <h3 className="font-bold text-gray-800 mb-4">Profile Info</h3>
            <div className="flex items-center gap-4 mb-4">
              <div className="relative group">
                <img src={page.profileImageUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-md object-cover" />
                <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                  <ImageIcon size={20} className="text-white" />
                </div>
              </div>
              <div className="flex-1 space-y-3">
                <input 
                  className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  placeholder="Page Title"
                  value={page.title}
                  onChange={(e) => updatePage({ title: e.target.value })}
                />
                <textarea 
                  className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  placeholder="Bio description..."
                  rows={2}
                  value={page.description}
                  onChange={(e) => updatePage({ description: e.target.value })}
                />
              </div>
            </div>
          </div>

          <div>
            <h3 className="font-bold text-gray-800 mb-4">Themes</h3>
            <div className="grid grid-cols-5 gap-3">
              {THEMES.map(theme => (
                <button 
                  key={theme.id}
                  onClick={() => updatePage({ themeColor: theme.color })}
                  className="w-full aspect-square rounded-xl shadow-inner border border-gray-100 flex items-center justify-center transition-transform hover:scale-105"
                  style={{ backgroundColor: theme.color }}
                >
                  {page.themeColor === theme.color && <Check size={20} className="text-white drop-shadow-md" />}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="font-bold text-gray-800 mb-4">Fonts</h3>
            <div className="space-y-2">
              {FONTS.map(font => (
                <button
                  key={font.id}
                  onClick={() => updatePage({ fontFamily: font.family })}
                  className={`w-full text-left px-4 py-3 rounded-xl border transition-all ${
                    page.fontFamily === font.family ? 'border-blue-500 bg-blue-50 text-blue-700 font-bold' : 'border-gray-100 hover:border-gray-200'
                  }`}
                  style={{ fontFamily: font.family }}
                >
                  {font.label}
                </button>
              ))}
            </div>
          </div>
        </section>
      </div>

      {/* Real-time Preview */}
      <div className="sticky top-24 h-fit hidden lg:block">
        <p className="text-center text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Live Preview</p>
        <div className="mx-auto w-[320px] h-[640px] border-[8px] border-gray-900 rounded-[3rem] shadow-2xl overflow-hidden bg-white relative">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-gray-900 rounded-b-2xl z-20"></div>
          <div 
            className="w-full h-full overflow-y-auto pt-12 p-6 flex flex-col items-center"
            style={{ fontFamily: page.fontFamily }}
          >
             <img src={page.profileImageUrl} className="w-20 h-20 rounded-full border-2 border-white shadow-lg mb-4" />
             <h2 className="font-bold text-lg mb-1">{page.title}</h2>
             <p className="text-xs text-gray-500 text-center mb-6 leading-relaxed">{page.description}</p>

             <div className="w-full space-y-3">
               {[1, 2, 3].map(i => (
                 <div 
                  key={i} 
                  className="w-full p-4 rounded-xl text-center text-sm font-semibold text-white shadow-sm"
                  style={{ backgroundColor: page.themeColor }}
                 >
                   Example Link #{i}
                 </div>
               ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DesignCustomizer;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { db } from '../services/db';
import { BioPage, BioLink } from '../types';
import { ExternalLink, AlertCircle } from 'lucide-react';

const PublicBio: React.FC = () => {
  const { username } = useParams<{ username: string }>();
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    if (username) {
      const p = db.getPageByUsername(username);
      if (p) {
        setPage(p);
        setLinks(db.getLinks(p.id).filter(l => l.isActive));
      } else {
        setNotFound(true);
      }
    }
  }, [username]);

  const handleLinkClick = (link: BioLink) => {
    // Analytics simulation
    const updatedLink = { ...link, clicks: link.clicks + 1 };
    db.saveLink(updatedLink);

    // In a real app, record IP/UA in separate table
    console.log(`Recorded click for ${link.title} from IP: simulation`);
  };

  if (notFound) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6 text-center">
        <AlertCircle size={64} className="text-gray-300 mb-4" />
        <h1 className="text-2xl font-bold text-gray-900 mb-2">Page Not Found</h1>
        <p className="text-gray-500 mb-6 max-w-sm">The BioLink profile @{username} doesn't exist or has been disabled.</p>
        <Link to="/register" className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold shadow-lg hover:shadow-xl transition-all">
          Create Your Own
        </Link>
      </div>
    );
  }

  if (!page) return null;

  return (
    <div 
      className="min-h-screen flex flex-col items-center pt-16 pb-24 px-6 transition-colors duration-500"
      style={{ fontFamily: page.fontFamily, backgroundColor: `${page.themeColor}08` }}
    >
      <div className="max-w-xl w-full flex flex-col items-center">
        <div className="relative mb-6">
          <div className="absolute inset-0 rounded-full blur-2xl opacity-20" style={{ backgroundColor: page.themeColor }}></div>
          <img 
            src={page.profileImageUrl} 
            className="w-24 h-24 rounded-full border-4 border-white shadow-xl relative z-10 object-cover" 
            alt={page.title}
          />
        </div>

        <h1 className="text-2xl font-extrabold text-gray-900 mb-2 tracking-tight">
          {page.title}
        </h1>

        <p className="text-gray-500 text-center mb-10 max-w-sm leading-relaxed">
          {page.description}
        </p>

        <div className="w-full space-y-4">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.url}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => handleLinkClick(link)}
              className="group w-full p-4 rounded-2xl bg-white border-2 border-transparent shadow-sm flex items-center justify-between transition-all hover:scale-[1.02] hover:shadow-md active:scale-95"
              style={{ 
                '--hover-color': page.themeColor,
                borderColor: 'white'
              } as any}
              onMouseEnter={(e) => e.currentTarget.style.borderColor = page.themeColor}
              onMouseLeave={(e) => e.currentTarget.style.borderColor = 'transparent'}
            >
              <span className="w-8"></span> {/* Placeholder for icon */}
              <span className="text-base font-bold text-gray-800 transition-colors group-hover:text-gray-900">
                {link.title}
              </span>
              <div className="w-8 h-8 rounded-full flex items-center justify-center bg-gray-50 text-gray-400 group-hover:bg-blue-50 group-hover:text-blue-500 transition-all">
                <ExternalLink size={14} />
              </div>
            </a>
          ))}
        </div>

        <footer className="mt-20">
          <Link to="/register" className="flex items-center gap-2 px-4 py-2 bg-white/50 backdrop-blur rounded-full border border-gray-100 shadow-sm text-xs font-bold text-gray-400 hover:text-gray-600 transition-colors">
            <span className="w-2 h-2 rounded-full bg-green-400"></span>
            Create your BioLink for free
          </Link>
        </footer>
      </div>
    </div>
  );
};

export default PublicBio;

import React from 'react';
import { User } from '../types';
import { db } from '../services/db';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface Props {
  user: User;
}

const Analytics: React.FC<Props> = ({ user }) => {
  const page = db.getPageByUsername(user.username);
  const links = page ? db.getLinks(page.id) : [];

  const data = links.map(l => ({
    name: l.title.length > 12 ? l.title.substring(0, 10) + '...' : l.title,
    clicks: l.clicks,
    color: l.isActive ? '#3b82f6' : '#94a3b8'
  }));

  const totalClicks = links.reduce((a, b) => a + b.clicks, 0);

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-2xl font-bold">Analytics</h1>
        <p className="text-gray-500">Track how your links are performing over time.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
         <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
            <h3 className="font-bold text-gray-800 mb-6">Clicks by Link</h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={data}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} />
                  <YAxis axisLine={false} tickLine={false} />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.05)'}}
                  />
                  <Bar dataKey="clicks" radius={[4, 4, 0, 0]}>
                    {data.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
         </div>

         <div className="space-y-6">
            <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-3xl text-white shadow-xl">
               <p className="text-blue-100 font-medium uppercase tracking-widest text-xs mb-2">Total Lifetime Clicks</p>
               <h2 className="text-5xl font-black mb-4">{totalClicks}</h2>
               <div className="flex items-center gap-2 text-sm text-blue-100">
                  <span className="bg-white/20 px-2 py-0.5 rounded-full">+12.5%</span>
                  <span>vs last month</span>
               </div>
            </div>

            <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
               <h3 className="font-bold text-gray-800 mb-4">Detailed Breakdown</h3>
               <div className="space-y-4">
                  {links.sort((a,b) => b.clicks - a.clicks).map(link => (
                    <div key={link.id} className="flex items-center justify-between">
                       <span className="text-sm text-gray-600 font-medium">{link.title}</span>
                       <div className="flex items-center gap-4">
                          <div className="w-24 bg-gray-100 h-2 rounded-full overflow-hidden">
                             <div 
                                className="bg-blue-500 h-full" 
                                style={{ width: `${totalClicks > 0 ? (link.clicks / totalClicks) * 100 : 0}%` }}
                             ></div>
                          </div>
                          <span className="text-sm font-bold text-gray-900">{link.clicks}</span>
                       </div>
                    </div>
                  ))}
               </div>
            </div>
         </div>
      </div>
    </div>
  );
};

export default Analytics;

import React, { useState } from 'react';
