import React, { useState, useEffect } from 'react';
import { User, BioPage, BioLink } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Check, Image as ImageIcon } from 'lucide-react';

interface Props {
  user: User;
}

const DesignCustomizer: React.FC<Props> = ({ user }) => {
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);

  useEffect(() => {
    const existing = db.getPageByUsername(user.username);
    if (existing) {
      setPage(existing);
      // Carrega os links reais do usuário para o preview
      setLinks(db.getLinks(existing.id).filter(l => l.isActive));
    } else {
      // Create default
      const newPage: BioPage = {
        id: Math.random().toString(36).substr(2, 9),
        userId: user.id,
        title: user.name,
        description: `Bem-vindo ao meu perfil!`,
        profileImageUrl: `https://picsum.photos/seed/${user.username}/200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true
      };
      db.savePage(newPage);
      setPage(newPage);
      setLinks([]);
    }
  }, [user]);

  const updatePage = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  if (!page) return null;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
      <div className="space-y-8">
        <div>
          <h1 className="text-2xl font-bold">Personalizar Design</h1>
          <p className="text-gray-500">Customize a aparência da sua página BioLink.</p>
        </div>

        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-6">
          <div>
            <h3 className="font-bold text-gray-800 mb-4">Informações do Perfil</h3>
            <div className="flex items-center gap-4 mb-4">
              <div className="relative group">
                <img src={page.profileImageUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-md object-cover" />
                <div className="absolute inset-0 bg-black/40 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                  <ImageIcon size={20} className="text-white" />
                </div>
              </div>
              <div className="flex-1 space-y-3">
                <input 
                  className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  placeholder="Título da Página"
                  value={page.title}
                  onChange={(e) => updatePage({ title: e.target.value })}
                />
                <textarea 
                  className="w-full px-4 py-2 bg-gray-50 border-none rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-sm"
                  placeholder="Descrição da bio..."
                  rows={2}
                  value={page.description}
                  onChange={(e) => updatePage({ description: e.target.value })}
                />
              </div>
            </div>
          </div>

          <div>
            <h3 className="font-bold text-gray-800 mb-4">Temas</h3>
            <div className="grid grid-cols-5 gap-3">
              {THEMES.map(theme => (
                <button 
                  key={theme.id}
                  onClick={() => updatePage({ themeColor: theme.color })}
                  className="w-full aspect-square rounded-xl shadow-inner border border-gray-100 flex items-center justify-center transition-transform hover:scale-105"
                  style={{ backgroundColor: theme.color }}
                >
                  {page.themeColor === theme.color && <Check size={20} className="text-white drop-shadow-md" />}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="font-bold text-gray-800 mb-4">Fontes</h3>
            <div className="space-y-2">
              {FONTS.map(font => (
                <button
                  key={font.id}
                  onClick={() => updatePage({ fontFamily: font.family })}
                  className={`w-full text-left px-4 py-3 rounded-xl border transition-all ${
                    page.fontFamily === font.family ? 'border-blue-500 bg-blue-50 text-blue-700 font-bold' : 'border-gray-100 hover:border-gray-200'
                  }`}
                  style={{ fontFamily: font.family }}
                >
                  {font.label}
                </button>
              ))}
            </div>
          </div>
        </section>
      </div>

      {/* Real-time Preview */}
      <div className="sticky top-24 h-fit hidden lg:block">
        <p className="text-center text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Visualização ao vivo</p>
        <div className="mx-auto w-[320px] h-[640px] border-[8px] border-gray-900 rounded-[3rem] shadow-2xl overflow-hidden bg-white relative">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-gray-900 rounded-b-2xl z-20"></div>
          <div 
            className="w-full h-full overflow-y-auto pt-12 p-6 flex flex-col items-center"
            style={{ fontFamily: page.fontFamily }}
          >
             <img src={page.profileImageUrl} className="w-20 h-20 rounded-full border-2 border-white shadow-lg mb-4 object-cover" />
             <h2 className="font-bold text-lg mb-1 text-center">{page.title}</h2>
             <p className="text-xs text-gray-500 text-center mb-6 leading-relaxed">{page.description}</p>

             <div className="w-full space-y-3">
               {links.length > 0 ? (
                 links.map(link => (
                   <div 
                    key={link.id} 
                    className="w-full p-4 rounded-xl text-center text-sm font-semibold text-white shadow-sm transition-all"
                    style={{ backgroundColor: page.themeColor }}
                   >
                     {link.title}
                   </div>
                 ))
               ) : (
                 <div className="w-full p-8 border-2 border-dashed border-gray-100 rounded-2xl text-center text-xs text-gray-300">
                    Nenhum link ativo para exibir no preview.
                 </div>
               )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DesignCustomizer;

