import React, { useState, useEffect, useRef } from 'react';
import { User, BioPage, BioLink } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Check, Image as ImageIcon, Paintbrush, MoveRight, Upload } from 'lucide-react';

interface Props {
  user: User;
}

const GRADIENTS = [
  'linear-gradient(to bottom, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)',
  'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)',
  'linear-gradient(to top, #cfd9df 0%, #e2ebf0 100%)',
  'linear-gradient(to right, #fa709a 0%, #fee140 100%)',
  'linear-gradient(to top, #30cfd0 0%, #330867 100%)',
];

const DesignCustomizer: React.FC<Props> = ({ user }) => {
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const existing = db.getPageByUsername(user.username);
    if (existing) {
      setPage({
        ...existing,
        backgroundType: existing.backgroundType || 'color',
        backgroundColor: existing.backgroundColor || '#ffffff',
        backgroundGradient: existing.backgroundGradient || GRADIENTS[0],
      } as BioPage);
      setLinks(db.getLinks(existing.id).filter(l => l.isActive));
    } else {
      const newPage: BioPage = {
        id: Math.random().toString(36).substr(2, 9),
        userId: user.id,
        title: user.name,
        description: `Bem-vindo ao meu perfil!`,
        profileImageUrl: `https://picsum.photos/seed/${user.username}/200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true,
        backgroundType: 'color',
        backgroundColor: '#ffffff',
        backgroundGradient: GRADIENTS[0],
      };
      db.savePage(newPage);
      setPage(newPage);
      setLinks([]);
    }
  }, [user]);

  const updatePage = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updatePage({ 
          backgroundImageUrl: reader.result as string,
          backgroundType: 'image'
        });
      };
      reader.readAsDataURL(file);
    }
  };

  if (!page) return null;

  const getBackgroundStyle = () => {
    if (page.backgroundType === 'color') return { backgroundColor: page.backgroundColor };
    if (page.backgroundType === 'gradient') return { backgroundImage: page.backgroundGradient };
    if (page.backgroundType === 'image') return { 
      backgroundImage: `url(${page.backgroundImageUrl})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center'
    };
    return { backgroundColor: '#ffffff' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
      <div className="space-y-8 pb-20">
        <div>
          <h1 className="text-2xl font-bold">Personalizar Design</h1>
          <p className="text-gray-500">Ajuste o visual da sua página pública.</p>
        </div>

        {/* Informações Básicas */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-6">
          <h3 className="font-bold text-gray-800 flex items-center gap-2"><Paintbrush size={18} /> Perfil</h3>
          <div className="flex items-center gap-4">
            <img src={page.profileImageUrl} className="w-16 h-16 rounded-full object-cover border-2 border-gray-100" />
            <div className="flex-1 space-y-2">
              <input 
                className="w-full px-4 py-2 bg-gray-50 rounded-xl outline-none text-sm focus:ring-2 focus:ring-blue-500"
                value={page.title}
                onChange={(e) => updatePage({ title: e.target.value })}
                placeholder="Título"
              />
              <input 
                className="w-full px-4 py-2 bg-gray-50 rounded-xl outline-none text-sm focus:ring-2 focus:ring-blue-500"
                value={page.description}
                onChange={(e) => updatePage({ description: e.target.value })}
                placeholder="Bio"
              />
            </div>
          </div>
        </section>

        {/* Background Selector */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-6">
          <h3 className="font-bold text-gray-800">Fundo da Página</h3>

          <div className="flex bg-gray-100 p-1 rounded-xl">
            {(['color', 'gradient', 'image'] as const).map((type) => (
              <button
                key={type}
                onClick={() => updatePage({ backgroundType: type })}
                className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all capitalize ${
                  page.backgroundType === type ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'
                }`}
              >
                {type === 'color' ? 'Cor' : type === 'gradient' ? 'Gradiente' : 'Imagem'}
              </button>
            ))}
          </div>

          {page.backgroundType === 'color' && (
            <div className="grid grid-cols-6 gap-2">
              {['#ffffff', '#f3f4f6', '#000000', '#ef4444', '#3b82f6', '#10b981'].map(color => (
                <button
                  key={color}
                  onClick={() => updatePage({ backgroundColor: color })}
                  className="aspect-square rounded-lg border border-gray-200"
                  style={{ backgroundColor: color }}
                >
                  {page.backgroundColor === color && <Check size={14} className={color === '#ffffff' ? 'text-black mx-auto' : 'text-white mx-auto'} />}
                </button>
              ))}
            </div>
          )}

          {page.backgroundType === 'gradient' && (
            <div className="grid grid-cols-3 gap-3">
              {GRADIENTS.map((grad, i) => (
                <button
                  key={i}
                  onClick={() => updatePage({ backgroundGradient: grad })}
                  className="h-12 rounded-lg border border-gray-200"
                  style={{ backgroundImage: grad }}
                >
                  {page.backgroundGradient === grad && <Check size={14} className="text-white mx-auto drop-shadow-md" />}
                </button>
              ))}
            </div>
          )}

          {page.backgroundType === 'image' && (
            <div className="space-y-4">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="w-full py-8 border-2 border-dashed border-gray-200 rounded-2xl flex flex-col items-center justify-center text-gray-400 hover:border-blue-400 hover:text-blue-500 transition-all"
              >
                {page.backgroundImageUrl ? (
                  <img src={page.backgroundImageUrl} className="h-20 w-32 object-cover rounded-lg mb-2" />
                ) : <Upload size={24} className="mb-2" />}
                <span className="text-xs font-bold">Clique para subir imagem</span>
              </button>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
            </div>
          )}
        </section>

        {/* Botões/Cores do Tema */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 space-y-4">
          <h3 className="font-bold text-gray-800">Cor dos Botões</h3>
          <div className="grid grid-cols-5 gap-3">
            {THEMES.map(theme => (
              <button 
                key={theme.id}
                onClick={() => updatePage({ themeColor: theme.color })}
                className="aspect-square rounded-full border-4 border-white shadow-sm flex items-center justify-center transition-transform hover:scale-110"
                style={{ backgroundColor: theme.color }}
              >
                {page.themeColor === theme.color && <Check size={16} className="text-white" />}
              </button>
            ))}
          </div>
        </section>
      </div>

      {/* Real-time Preview - Clicável */}
      <div className="sticky top-24 h-fit hidden lg:block">
        <p className="text-center text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Visualização Real (Clicável)</p>
        <div className="mx-auto w-[320px] h-[640px] border-[10px] border-gray-900 rounded-[3rem] shadow-2xl overflow-hidden relative bg-white">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-gray-900 rounded-b-2xl z-20"></div>

          <div 
            className="w-full h-full overflow-y-auto pt-14 p-6 flex flex-col items-center transition-all duration-500"
            style={{ 
              fontFamily: page.fontFamily,
              ...getBackgroundStyle()
            }}
          >
             <img src={page.profileImageUrl} className="w-20 h-20 rounded-full border-4 border-white shadow-lg mb-4 object-cover" />
             <h2 className={`font-bold text-lg mb-1 text-center ${page.backgroundColor === '#000000' ? 'text-white' : 'text-gray-900'}`}>{page.title}</h2>
             <p className={`text-xs text-center mb-8 px-4 leading-relaxed ${page.backgroundColor === '#000000' ? 'text-gray-400' : 'text-gray-500'}`}>{page.description}</p>

             <div className="w-full space-y-4">
               {links.length > 0 ? (
                 links.map(link => (
                   <a 
                    key={link.id} 
                    href={link.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="w-full p-4 rounded-2xl text-center text-sm font-bold text-white shadow-md transition-all hover:scale-105 active:scale-95 flex items-center justify-between group"
                    style={{ backgroundColor: page.themeColor }}
                   >
                     <span className="w-4"></span>
                     {link.title}
                     <MoveRight size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" />
                   </a>
                 ))
               ) : (
                 <div className="w-full p-8 border-2 border-dashed border-gray-200/50 rounded-2xl text-center text-xs text-gray-400 backdrop-blur-sm bg-white/30">
                    Crie links na aba "Links" para vê-los aqui.
                 </div>
               )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DesignCustomizer;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { db } from '../services/db';
import { BioPage, BioLink } from '../types';
import { ExternalLink, AlertCircle, ArrowRight } from 'lucide-react';

const PublicBio: React.FC = () => {
  const { username } = useParams<{ username: string }>();
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);
  const [notFound, setNotFound] = useState(false);

  useEffect(() => {
    if (username) {
      const p = db.getPageByUsername(username);
      if (p) {
        setPage(p);
        setLinks(db.getLinks(p.id).filter(l => l.isActive));
      } else {
        setNotFound(true);
      }
    }
  }, [username]);

  const handleLinkClick = (link: BioLink) => {
    const updatedLink = { ...link, clicks: link.clicks + 1 };
    db.saveLink(updatedLink);
  };

  if (notFound) {
    return (
      <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-center p-6 text-center">
        <AlertCircle size={64} className="text-gray-300 mb-4" />
        <h1 className="text-2xl font-bold text-gray-900 mb-2">Página não encontrada</h1>
        <p className="text-gray-500 mb-6 max-w-sm">O perfil @{username} ainda não foi criado ou está desativado.</p>
        <Link to="/register" className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold shadow-lg hover:shadow-xl transition-all">
          Criar minha página grátis
        </Link>
      </div>
    );
  }

  if (!page) return null;

  const getBackgroundStyle = () => {
    if (page.backgroundType === 'color') return { backgroundColor: page.backgroundColor };
    if (page.backgroundType === 'gradient') return { backgroundImage: page.backgroundGradient };
    if (page.backgroundType === 'image') return { 
      backgroundImage: `url(${page.backgroundImageUrl})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      backgroundAttachment: 'fixed'
    };
    return { backgroundColor: '#ffffff' };
  };

  const isDarkBackground = page.backgroundType === 'color' && page.backgroundColor === '#000000';

  return (
    <div 
      className="min-h-screen flex flex-col items-center pt-16 pb-24 px-6 transition-all duration-700"
      style={{ 
        fontFamily: page.fontFamily,
        ...getBackgroundStyle()
      }}
    >
      <div className="max-w-xl w-full flex flex-col items-center">
        <div className="relative mb-6">
          <div className="absolute inset-0 rounded-full blur-3xl opacity-30" style={{ backgroundColor: page.themeColor }}></div>
          <img 
            src={page.profileImageUrl} 
            className="w-28 h-28 rounded-full border-4 border-white shadow-2xl relative z-10 object-cover" 
            alt={page.title}
          />
        </div>

        <h1 className={`text-2xl font-black mb-2 tracking-tight ${isDarkBackground ? 'text-white' : 'text-gray-900'}`}>
          {page.title}
        </h1>

        <p className={`text-center mb-10 max-w-sm leading-relaxed font-medium ${isDarkBackground ? 'text-gray-400' : 'text-gray-500'}`}>
          {page.description}
        </p>

        <div className="w-full space-y-4">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.url}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() => handleLinkClick(link)}
              className="group w-full p-5 rounded-2xl shadow-lg flex items-center justify-between transition-all hover:scale-[1.03] active:scale-95 text-white"
              style={{ backgroundColor: page.themeColor }}
            >
              <span className="w-6"></span>
              <span className="text-base font-bold tracking-wide">
                {link.title}
              </span>
              <div className="w-8 h-8 rounded-full flex items-center justify-center bg-white/20 group-hover:bg-white/40 transition-colors">
                <ArrowRight size={16} />
              </div>
            </a>
          ))}
        </div>

        <footer className="mt-24">
          <Link to="/register" className="flex items-center gap-2 px-5 py-2.5 bg-white/10 backdrop-blur-md rounded-full border border-white/20 shadow-xl text-xs font-bold text-gray-800 hover:bg-white/20 transition-all">
            <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></span>
            Crie seu BioLink grátis
          </Link>
        </footer>
      </div>
    </div>
  );
};

export default PublicBio;

import React, { useState, useEffect } from 'react';
import { User, BioLink } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, ExternalLink, GripVertical, ToggleLeft, ToggleRight, MessageCircle } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLink, setNewLink] = useState({ title: '', url: '' });
  const [whatsappData, setWhatsappData] = useState({ phone: '', message: '' });
  const [isAdding, setIsAdding] = useState(false);
  const [isWhatsappMode, setIsWhatsappMode] = useState(false);

  const page = db.getPageByUsername(user.username);

  useEffect(() => {
    if (page) {
      setLinks(db.getLinks(page.id));
    }
  }, [page?.id]);

  const handleAddLink = () => {
    if (!page) return;

    let finalUrl = newLink.url;
    let finalTitle = newLink.title;

    if (isWhatsappMode) {
      const cleanPhone = whatsappData.phone.replace(/\D/g, '');
      const encodedMsg = encodeURIComponent(whatsappData.message);
      finalUrl = `https://wa.me/${cleanPhone}${encodedMsg ? `?text=${encodedMsg}` : ''}`;
      if (!finalTitle) finalTitle = 'Fale comigo no WhatsApp';
    }

    if (!finalTitle || !finalUrl) return;

    const link: BioLink = {
      id: Math.random().toString(36).substr(2, 9),
      bioPageId: page.id,
      title: finalTitle,
      url: finalUrl.startsWith('http') ? finalUrl : `https://${finalUrl}`,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    db.saveLink(link);
    setLinks([...links, link]);
    resetForm();
  };

  const resetForm = () => {
    setNewLink({ title: '', url: '' });
    setWhatsappData({ phone: '', message: '' });
    setIsAdding(false);
    setIsWhatsappMode(false);
  };

  const toggleLink = (id: string) => {
    const updated = links.map(l => {
      if (l.id === id) {
        const newL = { ...l, isActive: !l.isActive };
        db.saveLink(newL);
        return newL;
      }
      return l;
    });
    setLinks(updated);
  };

  const deleteLink = (id: string) => {
    db.deleteLink(id);
    setLinks(links.filter(l => l.id !== id));
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Meus Links</h1>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-md active:scale-95"
        >
          <Plus size={20} /> Adicionar Link
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl shadow-lg border-2 border-blue-100 animate-in slide-in-from-top duration-300">
          <div className="flex gap-4 mb-6 p-1 bg-gray-100 rounded-xl">
            <button 
              onClick={() => setIsWhatsappMode(false)}
              className={`flex-1 py-2 rounded-lg text-xs font-bold transition-all ${!isWhatsappMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500'}`}
            >
              Link Comum
            </button>
            <button 
              onClick={() => setIsWhatsappMode(true)}
              className={`flex-1 py-2 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-2 ${isWhatsappMode ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500'}`}
            >
              <MessageCircle size={14} /> WhatsApp
            </button>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-1">Título do Botão</label>
              <input 
                type="text" 
                placeholder={isWhatsappMode ? "Ex: Me chame no Zap" : "Ex: Meu Site"}
                value={newLink.title}
                onChange={e => setNewLink({ ...newLink, title: e.target.value })}
                className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
              />
            </div>

            {isWhatsappMode ? (
              <>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Telefone (com DDD)</label>
                    <input 
                      type="text" 
                      placeholder="Ex: 11999999999"
                      value={whatsappData.phone}
                      onChange={e => setWhatsappData({ ...whatsappData, phone: e.target.value })}
                      className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-1">Mensagem Inicial (opcional)</label>
                    <input 
                      type="text" 
                      placeholder="Ex: Olá, gostaria de saber mais!"
                      value={whatsappData.message}
                      onChange={e => setWhatsappData({ ...whatsappData, message: e.target.value })}
                      className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                    />
                  </div>
                </div>
              </>
            ) : (
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">URL (Destino)</label>
                <input 
                  type="text" 
                  placeholder="https://exemplo.com.br"
                  value={newLink.url}
                  onChange={e => setNewLink({ ...newLink, url: e.target.value })}
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>
            )}

            <div className="flex gap-3 justify-end pt-4 border-t border-gray-50">
              <button onClick={resetForm} className="px-6 py-2 text-gray-500 font-bold hover:bg-gray-50 rounded-xl transition-all">Cancelar</button>
              <button 
                onClick={handleAddLink} 
                className={`px-8 py-3 rounded-xl font-bold text-white shadow-lg transition-all active:scale-95 ${isWhatsappMode ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}
              >
                Salvar Link
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {links.map((link) => (
          <div key={link.id} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex items-center gap-4 hover:border-blue-100 transition-all group">
            <div className="text-gray-300 cursor-grab active:cursor-grabbing">
              <GripVertical size={20} />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <h4 className="font-bold text-gray-900 truncate">{link.title}</h4>
                {link.url.includes('wa.me') && <MessageCircle size={14} className="text-green-500" />}
                {!link.isActive && <span className="text-[9px] bg-gray-100 text-gray-400 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">Inativo</span>}
              </div>
              <p className="text-xs text-gray-400 truncate">{link.url}</p>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={() => toggleLink(link.id)}
                className={`p-2 rounded-xl transition-all ${link.isActive ? 'text-blue-500 bg-blue-50' : 'text-gray-300 bg-gray-50'}`}
              >
                {link.isActive ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
              </button>
              <button 
                onClick={() => deleteLink(link.id)}
                className="p-2.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              >
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
        {links.length === 0 && !isAdding && (
          <div className="bg-white border-2 border-dashed border-gray-100 rounded-[2.5rem] p-16 text-center">
            <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
               <Plus className="text-gray-300" size={32} />
            </div>
            <p className="text-gray-400 font-medium mb-6">Você ainda não tem links criados.</p>
            <button onClick={() => setIsAdding(true)} className="bg-gray-900 text-white px-8 py-3 rounded-2xl font-bold hover:bg-black transition-all">
              Começar agora
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default LinksManager;

import React, { useState, useEffect } from 'react';
import { User, BioLink } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, GripVertical, ToggleLeft, ToggleRight, MessageCircle, X } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLink, setNewLink] = useState({ title: '', url: '' });
  const [whatsappData, setWhatsappData] = useState({ phone: '', message: '' });
  const [isAdding, setIsAdding] = useState(false);
  const [isWhatsappMode, setIsWhatsappMode] = useState(false);

  const page = db.getPageByUsername(user.username);

  useEffect(() => {
    if (page) {
      setLinks(db.getLinks(page.id));
    }
  }, [page?.id]);

  const handleAddLink = () => {
    if (!page) return;

    let finalUrl = '';
    let finalTitle = newLink.title;

    if (isWhatsappMode) {
      const cleanPhone = whatsappData.phone.replace(/\D/g, '');
      if (!cleanPhone) {
        alert("Por favor, insira um número de telefone válido.");
        return;
      }
      const encodedMsg = encodeURIComponent(whatsappData.message);
      finalUrl = `https://wa.me/${cleanPhone}${encodedMsg ? `?text=${encodedMsg}` : ''}`;
      if (!finalTitle) finalTitle = 'Fale comigo no WhatsApp';
    } else {
      finalUrl = newLink.url;
      if (!finalUrl.startsWith('http')) {
        finalUrl = `https://${finalUrl}`;
      }
    }

    if (!finalTitle || !finalUrl) {
      alert("Preencha todos os campos obrigatórios.");
      return;
    }

    const link: BioLink = {
      id: Math.random().toString(36).substr(2, 9),
      bioPageId: page.id,
      title: finalTitle,
      url: finalUrl,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    db.saveLink(link);
    setLinks([...links, link]);
    resetForm();
  };

  const resetForm = () => {
    setNewLink({ title: '', url: '' });
    setWhatsappData({ phone: '', message: '' });
    setIsAdding(false);
    setIsWhatsappMode(false);
  };

  const toggleLink = (id: string) => {
    const updated = links.map(l => {
      if (l.id === id) {
        const newL = { ...l, isActive: !l.isActive };
        db.saveLink(newL);
        return newL;
      }
      return l;
    });
    setLinks(updated);
  };

  const deleteLink = (id: string) => {
    db.deleteLink(id);
    setLinks(links.filter(l => l.id !== id));
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900">Meus Links</h1>
        {!isAdding && (
          <button 
            onClick={() => setIsAdding(true)}
            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus size={20} /> Adicionar Novo
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-3xl shadow-xl border-2 border-blue-50 animate-in fade-in zoom-in duration-300">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-gray-800 text-lg">Novo Link</h3>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
              <X size={20} />
            </button>
          </div>

          <div className="flex gap-2 mb-6 p-1 bg-gray-100 rounded-2xl">
            <button 
              onClick={() => setIsWhatsappMode(false)}
              className={`flex-1 py-3 rounded-xl text-sm font-bold transition-all ${!isWhatsappMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Link Personalizado
            </button>
            <button 
              onClick={() => setIsWhatsappMode(true)}
              className={`flex-1 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2 ${isWhatsappMode ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              <MessageCircle size={18} /> WhatsApp
            </button>
          </div>

          <div className="space-y-5">
            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Título do Botão</label>
              <input 
                type="text" 
                placeholder={isWhatsappMode ? "Ex: Me chama no WhatsApp" : "Ex: Visite meu Site"}
                value={newLink.title}
                onChange={e => setNewLink({ ...newLink, title: e.target.value })}
                className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              />
            </div>

            {isWhatsappMode ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Telefone (DDD + Número)</label>
                  <input 
                    type="text" 
                    placeholder="Ex: 11999999999"
                    value={whatsappData.phone}
                    onChange={e => setWhatsappData({ ...whatsappData, phone: e.target.value })}
                    className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mensagem Inicial</label>
                  <input 
                    type="text" 
                    placeholder="Olá! Gostaria de mais informações."
                    value={whatsappData.message}
                    onChange={e => setWhatsappData({ ...whatsappData, message: e.target.value })}
                    className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none"
                  />
                </div>
              </div>
            ) : (
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">URL de Destino</label>
                <input 
                  type="text" 
                  placeholder="exemplo.com.br"
                  value={newLink.url}
                  onChange={e => setNewLink({ ...newLink, url: e.target.value })}
                  className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            )}

            <div className="flex gap-3 justify-end pt-6 border-t border-gray-100">
              <button onClick={resetForm} className="px-6 py-3 text-gray-500 font-bold hover:bg-gray-100 rounded-2xl transition-all">Descartar</button>
              <button 
                onClick={handleAddLink} 
                className={`px-10 py-3.5 rounded-2xl font-bold text-white shadow-xl transition-all active:scale-95 ${isWhatsappMode ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}
              >
                Adicionar Link
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {links.map((link) => (
          <div key={link.id} className={`bg-white p-5 rounded-3xl shadow-sm border ${link.isActive ? 'border-gray-100' : 'border-gray-50 opacity-60'} flex items-center gap-4 transition-all`}>
            <div className="text-gray-300">
              <GripVertical size={20} />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <h4 className="font-bold text-gray-900 truncate">{link.title}</h4>
                {link.url.includes('wa.me') && <span className="bg-green-100 text-green-600 text-[10px] px-2 py-0.5 rounded-full font-bold">WhatsApp</span>}
              </div>
              <p className="text-xs text-gray-400 truncate font-medium">{link.url}</p>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={() => toggleLink(link.id)}
                className={`p-1.5 rounded-xl transition-all ${link.isActive ? 'text-blue-500' : 'text-gray-300'}`}
              >
                {link.isActive ? <ToggleRight size={36} /> : <ToggleLeft size={36} />}
              </button>
              <button 
                onClick={() => deleteLink(link.id)}
                className="p-3 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all"
              >
                <Trash2 size={20} />
              </button>
            </div>
          </div>
        ))}
        {links.length === 0 && !isAdding && (
          <div className="bg-white border-4 border-dashed border-gray-50 rounded-[3rem] p-20 text-center">
            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
               <Plus className="text-gray-200" size={40} />
            </div>
            <p className="text-gray-400 font-bold mb-8">Sua lista de links está vazia</p>
            <button onClick={() => setIsAdding(true)} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black shadow-xl shadow-blue-100 hover:scale-105 transition-all">
              Criar meu primeiro link
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default LinksManager;

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { db } from '../services/db';
import { User } from '../types';
import { Mail, ShieldCheck, CheckCircle2 } from 'lucide-react';

interface Props {
  onRegister: (user: User, token: string) => void;
}

const Register: React.FC<Props> = ({ onRegister }) => {
  const [formData, setFormData] = useState({ name: '', email: '', username: '', password: 'Mudar@123' });
  const [error, setError] = useState('');
  const [showWelcome, setShowWelcome] = useState(false);
  const [registeredUser, setRegisteredUser] = useState<User | null>(null);
  const navigate = useNavigate();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (db.findUserByUsername(formData.username)) {
      setError('Este nome de usuário já está em uso. Tente outro.');
      return;
    }

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: formData.name,
      email: formData.email,
      username: formData.username.toLowerCase().replace(/[^a-z0-9_]/g, ''),
      createdAt: new Date().toISOString(),
    };

    db.saveUser(newUser);
    setRegisteredUser(newUser);
    setShowWelcome(true);
  };

  const handleProceed = () => {
    if (registeredUser) {
      onRegister(registeredUser, 'mock-jwt-token');
      navigate('/dashboard');
    }
  };

  if (showWelcome) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
        <div className="bg-white w-full max-w-md p-10 rounded-[2.5rem] shadow-2xl text-center animate-in zoom-in duration-500">
          <div className="w-20 h-20 bg-green-50 text-green-500 rounded-full flex items-center justify-center mx-auto mb-6">
            <CheckCircle2 size={48} />
          </div>
          <h2 className="text-3xl font-black text-gray-900 mb-2">Quase lá, {registeredUser?.name.split(' ')[0]}!</h2>
          <p className="text-gray-500 font-medium mb-8">
            Enviamos um e-mail de boas-vindas para <span className="text-gray-900 font-bold">{registeredUser?.email}</span> com seus dados de acesso.
          </p>

          <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 text-left mb-8 space-y-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-lg shadow-sm text-blue-600"><Mail size={18} /></div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Seu Login</p>
                <p className="font-bold text-gray-800">{registeredUser?.email}</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white rounded-lg shadow-sm text-blue-600"><ShieldCheck size={18} /></div>
              <div>
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Sua Senha Padrão</p>
                <p className="font-bold text-gray-800">Mudar@123</p>
              </div>
            </div>
          </div>

          <button 
            onClick={handleProceed}
            className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
          >
            Acessar meu Painel agora
          </button>

          <p className="mt-6 text-xs text-gray-400 font-medium italic">
            * Lembre-se de verificar sua caixa de spam.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex items-center justify-center p-6">
      <div className="bg-white w-full max-w-md p-8 rounded-[2.5rem] shadow-xl border border-gray-100">
        <div className="text-center mb-8">
          <h1 className="text-4xl font-black bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent inline-block">BioLink</h1>
          <p className="text-gray-400 font-bold mt-2">Crie sua página em segundos</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && <div className="p-4 bg-red-50 text-red-500 text-sm font-bold rounded-2xl border border-red-100">{error}</div>}

          <div>
            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome Completo</label>
            <input 
              required
              className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium"
              value={formData.name}
              onChange={e => setFormData({ ...formData, name: e.target.value })}
              placeholder="Ex: João Silva"
            />
          </div>

          <div>
            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">E-mail</label>
            <input 
              type="email"
              required
              className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium"
              value={formData.email}
              onChange={e => setFormData({ ...formData, email: e.target.value })}
              placeholder="seu@email.com"
            />
          </div>

          <div>
            <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Nome de Usuário (Sua URL)</label>
            <div className="relative">
              <span className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300 font-bold">@</span>
              <input 
                required
                className="w-full pl-10 pr-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all font-bold text-blue-600"
                value={formData.username}
                onChange={e => setFormData({ ...formData, username: e.target.value.toLowerCase() })}
                placeholder="seu_nome"
              />
            </div>
            <p className="text-[10px] text-gray-400 mt-2 ml-1">Seu link será: biolink.io/<b>{formData.username || 'seu_nome'}</b></p>
          </div>

          <div className="pt-4">
            <button className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-[0.98] transition-all">
              Criar Minha Conta Grátis
            </button>
          </div>
        </form>

        <p className="text-center mt-8 text-sm text-gray-400 font-bold">
          Já tem uma conta? <Link to="/login" className="text-blue-600 hover:underline">Entrar</Link>
        </p>
      </div>
    </div>
  );
};

export default Register;

import React, { useState, useEffect } from 'react';
import { User, BioLink } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, GripVertical, ToggleLeft, ToggleRight, MessageCircle, X } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLink, setNewLink] = useState({ title: '', url: '' });
  const [whatsappData, setWhatsappData] = useState({ phone: '', message: '' });
  const [isAdding, setIsAdding] = useState(false);
  const [isWhatsappMode, setIsWhatsappMode] = useState(false);

  const page = db.getPageByUsername(user.username);

  useEffect(() => {
    if (page) {
      setLinks(db.getLinks(page.id));
    }
  }, [page?.id]);

  const handleAddLink = () => {
    if (!page) {
      alert("Erro: Página de bio não encontrada.");
      return;
    }

    let finalUrl = '';
    let finalTitle = newLink.title.trim();

    if (isWhatsappMode) {
      const cleanPhone = whatsappData.phone.replace(/\D/g, '');
      if (!cleanPhone || cleanPhone.length < 10) {
        alert("Por favor, insira um número de telefone válido com DDD (apenas números).");
        return;
      }
      const encodedMsg = encodeURIComponent(whatsappData.message);
      finalUrl = `https://wa.me/${cleanPhone}${encodedMsg ? `?text=${encodedMsg}` : ''}`;
      if (!finalTitle) finalTitle = 'WhatsApp';
    } else {
      finalUrl = newLink.url.trim();
      if (!finalUrl) {
        alert("Por favor, insira uma URL.");
        return;
      }
      // Adiciona https:// se o usuário esquecer
      if (!finalUrl.startsWith('http://') && !finalUrl.startsWith('https://')) {
        finalUrl = `https://${finalUrl}`;
      }
      if (!finalTitle) finalTitle = 'Novo Link';
    }

    const link: BioLink = {
      id: Math.random().toString(36).substr(2, 9),
      bioPageId: page.id,
      title: finalTitle,
      url: finalUrl,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    // Salva no banco simulado
    db.saveLink(link);

    // Atualiza o estado local para refletir a mudança imediatamente
    setLinks(prev => [...prev, link]);

    // Reseta o formulário
    resetForm();
  };

  const resetForm = () => {
    setNewLink({ title: '', url: '' });
    setWhatsappData({ phone: '', message: '' });
    setIsAdding(false);
    setIsWhatsappMode(false);
  };

  const toggleLink = (id: string) => {
    const updated = links.map(l => {
      if (l.id === id) {
        const newL = { ...l, isActive: !l.isActive };
        db.saveLink(newL);
        return newL;
      }
      return l;
    });
    setLinks(updated);
  };

  const deleteLink = (id: string) => {
    if (confirm("Tem certeza que deseja excluir este link?")) {
      db.deleteLink(id);
      setLinks(prev => prev.filter(l => l.id !== id));
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pb-20">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900">Meus Links</h1>
        {!isAdding && (
          <button 
            onClick={() => setIsAdding(true)}
            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-blue-700 transition-all shadow-md active:scale-95"
          >
            <Plus size={20} /> Adicionar Novo
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-3xl shadow-xl border-2 border-blue-50 animate-in fade-in zoom-in duration-300">
          <div className="flex justify-between items-center mb-6">
            <h3 className="font-bold text-gray-800 text-lg">Configurar Botão</h3>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600 p-2">
              <X size={20} />
            </button>
          </div>

          <div className="flex gap-2 mb-6 p-1 bg-gray-100 rounded-2xl">
            <button 
              type="button"
              onClick={() => setIsWhatsappMode(false)}
              className={`flex-1 py-3 rounded-xl text-sm font-bold transition-all ${!isWhatsappMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              Site / Link
            </button>
            <button 
              type="button"
              onClick={() => setIsWhatsappMode(true)}
              className={`flex-1 py-3 rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2 ${isWhatsappMode ? 'bg-white text-green-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
            >
              <MessageCircle size={18} /> WhatsApp
            </button>
          </div>

          <div className="space-y-5">
            <div>
              <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Título do Botão</label>
              <input 
                type="text" 
                placeholder={isWhatsappMode ? "Ex: Fale Conosco" : "Ex: Meu Portfólio"}
                value={newLink.title}
                onChange={e => setNewLink({ ...newLink, title: e.target.value })}
                className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              />
            </div>

            {isWhatsappMode ? (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Telefone (DDD + Número)</label>
                  <input 
                    type="text" 
                    placeholder="Ex: 11999999999"
                    value={whatsappData.phone}
                    onChange={e => setWhatsappData({ ...whatsappData, phone: e.target.value })}
                    className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mensagem Inicial</label>
                  <input 
                    type="text" 
                    placeholder="Olá! Gostaria de mais informações."
                    value={whatsappData.message}
                    onChange={e => setWhatsappData({ ...whatsappData, message: e.target.value })}
                    className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none"
                  />
                </div>
              </div>
            ) : (
              <div>
                <label className="block text-xs font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">URL (Destino)</label>
                <input 
                  type="text" 
                  placeholder="www.seusite.com.br"
                  value={newLink.url}
                  onChange={e => setNewLink({ ...newLink, url: e.target.value })}
                  className="w-full px-5 py-3.5 bg-gray-50 border border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                />
              </div>
            )}

            <div className="flex gap-3 justify-end pt-6 border-t border-gray-100">
              <button type="button" onClick={resetForm} className="px-6 py-3 text-gray-500 font-bold hover:bg-gray-100 rounded-2xl transition-all">Cancelar</button>
              <button 
                type="button"
                onClick={handleAddLink} 
                className={`px-10 py-3.5 rounded-2xl font-bold text-white shadow-xl transition-all active:scale-95 ${isWhatsappMode ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}
              >
                Salvar Link
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="space-y-4">
        {links.length > 0 ? (
          links.map((link) => (
            <div key={link.id} className={`bg-white p-5 rounded-3xl shadow-sm border ${link.isActive ? 'border-gray-100' : 'border-gray-50 opacity-60'} flex items-center gap-4 transition-all`}>
              <div className="text-gray-300">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 min-w-0 text-left">
                <div className="flex items-center gap-2 mb-1">
                  <h4 className="font-bold text-gray-900 truncate">{link.title}</h4>
                  {link.url.includes('wa.me') && <span className="bg-green-100 text-green-600 text-[10px] px-2 py-0.5 rounded-full font-bold">WhatsApp</span>}
                </div>
                <p className="text-xs text-gray-400 truncate font-medium">{link.url}</p>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => toggleLink(link.id)}
                  className={`p-1.5 rounded-xl transition-all ${link.isActive ? 'text-blue-500' : 'text-gray-300'}`}
                  title={link.isActive ? "Desativar" : "Ativar"}
                >
                  {link.isActive ? <ToggleRight size={36} /> : <ToggleLeft size={36} />}
                </button>
                <button 
                  onClick={() => deleteLink(link.id)}
                  className="p-3 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all"
                  title="Excluir"
                >
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          ))
        ) : !isAdding && (
          <div className="bg-white border-4 border-dashed border-gray-50 rounded-[3rem] p-20 text-center">
            <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
