import React, { useState, useEffect } from 'react';
import { User, BioLink } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, GripVertical, ToggleLeft, ToggleRight, MessageCircle, X, Check } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLinkTitle, setNewLinkTitle] = useState('');
  const [newLinkUrl, setNewLinkUrl] = useState('');
  const [whatsappPhone, setWhatsappPhone] = useState('');
  const [whatsappMessage, setWhatsappMessage] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isWhatsappMode, setIsWhatsappMode] = useState(false);

  const page = db.getPageByUsername(user.username);

  // Carrega os links do banco ao montar ou quando o id da página muda
  const loadLinks = () => {
    if (page) {
      const storedLinks = db.getLinks(page.id);
      setLinks(storedLinks);
    }
  };

  useEffect(() => {
    loadLinks();
  }, [page?.id]);

  const resetForm = () => {
    setNewLinkTitle('');
    setNewLinkUrl('');
    setWhatsappPhone('');
    setWhatsappMessage('');
    setIsAdding(false);
    setIsWhatsappMode(false);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault(); // Crucial para evitar que o navegador recarregue

    if (!page) {
      alert("Erro crítico: Página não encontrada.");
      return;
    }

    let finalUrl = '';
    let finalTitle = newLinkTitle.trim();

    if (isWhatsappMode) {
      const cleanPhone = whatsappPhone.replace(/\D/g, '');
      if (!cleanPhone || cleanPhone.length < 10) {
        alert("Digite um telefone válido com DDD (ex: 11999999999)");
        return;
      }
      const encodedMsg = encodeURIComponent(whatsappMessage);
      finalUrl = `https://wa.me/${cleanPhone}${encodedMsg ? `?text=${encodedMsg}` : ''}`;
      if (!finalTitle) finalTitle = 'WhatsApp';
    } else {
      let urlInput = newLinkUrl.trim();
      if (!urlInput) {
        alert("A URL do link é obrigatória.");
        return;
      }

      // Garante que a URL tenha o protocolo
      if (!urlInput.startsWith('http://') && !urlInput.startsWith('https://')) {
        urlInput = `https://${urlInput}`;
      }
      finalUrl = urlInput;
      if (!finalTitle) finalTitle = 'Link Útil';
    }

    const newLinkObj: BioLink = {
      id: `link_${Math.random().toString(36).substr(2, 9)}`,
      bioPageId: page.id,
      title: finalTitle,
      url: finalUrl,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    try {
      db.saveLink(newLinkObj);
      loadLinks(); // Recarrega do storage para garantir sincronia
      resetForm();
    } catch (err) {
      alert("Erro ao salvar no banco de dados.");
      console.error(err);
    }
  };

  const toggleLinkStatus = (id: string) => {
    const link = links.find(l => l.id === id);
    if (link) {
      const updated = { ...link, isActive: !link.isActive };
      db.saveLink(updated);
      setLinks(links.map(l => l.id === id ? updated : l));
    }
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Deseja realmente excluir este link?")) {
      db.deleteLink(id);
      setLinks(prev => prev.filter(l => l.id !== id));
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pb-20">
      <div className="flex justify-between items-center mb-2">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Gerenciar Links</h1>
          <p className="text-sm text-gray-400 font-medium">Adicione ou edite os botões da sua página.</p>
        </div>
        {!isAdding && (
          <button 
            onClick={() => setIsAdding(true)}
            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100 active:scale-95"
          >
            <Plus size={20} /> Novo Botão
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl border border-blue-50 animate-in fade-in slide-in-from-top-4 duration-300">
          <form onSubmit={handleSave} className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="font-black text-xl text-gray-800">Novo Link</h3>
              <button type="button" onClick={resetForm} className="text-gray-400 hover:text-red-500 p-2 bg-gray-50 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <div className="flex p-1.5 bg-gray-100 rounded-[1.25rem]">
              <button 
                type="button"
                onClick={() => setIsWhatsappMode(false)}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${!isWhatsappMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}
              >
                Link Normal
              </button>
              <button 
                type="button"
                onClick={() => setIsWhatsappMode(true)}
                className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${isWhatsappMode ? 'bg-white text-green-600 shadow-sm' : 'text-gray-400'}`}
              >
                <MessageCircle size={14} /> WhatsApp
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Nome do Botão</label>
                <input 
                  type="text" 
                  autoFocus
                  placeholder={isWhatsappMode ? "Ex: Me chama no Zap" : "Ex: Acesse meu Site"}
                  value={newLinkTitle}
                  onChange={e => setNewLinkTitle(e.target.value)}
                  className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-bold"
                />
              </div>

              {isWhatsappMode ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Número do WhatsApp</label>
                    <input 
                      type="tel" 
                      placeholder="Ex: 11999999999"
                      value={whatsappPhone}
                      onChange={e => setWhatsappPhone(e.target.value)}
                      className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none font-bold"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Mensagem Inicial (Opcial)</label>
                    <input 
                      type="text" 
                      placeholder="Olá, vim pela Bio!"
                      value={whatsappMessage}
                      onChange={e => setWhatsappMessage(e.target.value)}
                      className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-green-500 outline-none font-bold"
                    />
                  </div>
                </div>
              ) : (
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">URL (Destino)</label>
                  <input 
                    type="text" 
                    placeholder="www.seusite.com.br"
                    value={newLinkUrl}
                    onChange={e => setNewLinkUrl(e.target.value)}
                    className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none font-bold"
                  />
                </div>
              )}
            </div>

            <div className="flex gap-4 pt-4">
              <button 
                type="button" 
                onClick={resetForm} 
                className="flex-1 px-6 py-4 text-gray-500 font-black text-sm uppercase tracking-widest hover:bg-gray-50 rounded-2xl transition-all"
              >
                Cancelar
              </button>
              <button 
                type="submit"
                className={`flex-1 px-6 py-4 rounded-2xl font-black text-sm uppercase tracking-widest text-white shadow-xl transition-all active:scale-95 flex items-center justify-center gap-2 ${isWhatsappMode ? 'bg-green-600 hover:bg-green-700 shadow-green-100' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-100'}`}
              >
                <Check size={18} /> Salvar Link
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="space-y-4">
        {links.length > 0 ? (
          links.map((link) => (
            <div 
              key={link.id} 
              className={`bg-white p-6 rounded-[2rem] shadow-sm border transition-all flex items-center gap-4 group ${link.isActive ? 'border-gray-100' : 'border-gray-50 bg-gray-50/30'}`}
            >
              <div className="text-gray-300 cursor-grab active:cursor-grabbing">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 mb-1">
                  <h4 className={`font-black text-base truncate ${link.isActive ? 'text-gray-900' : 'text-gray-400'}`}>
                    {link.title}
                  </h4>
                  {link.url.includes('wa.me') && (
                    <span className="bg-green-100 text-green-600 text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-full">WhatsApp</span>
                  )}
                </div>
                <p className="text-xs text-gray-400 truncate font-medium">{link.url}</p>
              </div>
              <div className="flex items-center gap-2">
                <button 
                  onClick={() => toggleLinkStatus(link.id)}
                  className={`p-1.5 rounded-xl transition-all ${link.isActive ? 'text-blue-600' : 'text-gray-300'}`}
                  title={link.isActive ? "Desativar" : "Ativar"}
                >
                  {link.isActive ? <ToggleRight size={40} /> : <ToggleLeft size={40} />}
                </button>
                <button 
                  onClick={() => handleDelete(link.id)}
                  className="p-3 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"
                  title="Excluir"
                >
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          ))
        ) : !isAdding && (
          <div className="bg-white border-4 border-dashed border-gray-50 rounded-[3rem] p-20 text-center">
            <div className="w-24 h-24 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
               <MessageCircle className="text-gray-100" size={48} />
            </div>
            <h3 className="text-xl font-black text-gray-900 mb-2">Sua página está vazia</h3>
            <p className="text-gray-400 font-medium mb-10 max-w-xs mx-auto">Adicione seu primeiro link ou botão de WhatsApp para começar a compartilhar.</p>
            <button 
              onClick={() => setIsAdding(true)} 
              className="bg-blue-600 text-white px-12 py-5 rounded-[2rem] font-black shadow-2xl shadow-blue-200 hover:scale-105 transition-all"
            >
              Criar meu primeiro link
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default LinksManager;

