import React, { useState, useEffect, useRef } from 'react';
import { User, BioPage, BioLink } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Check, Image as ImageIcon, Paintbrush, MoveRight, Upload, Camera } from 'lucide-react';

interface Props {
  user: User;
}

const GRADIENTS = [
  'linear-gradient(to bottom, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)',
  'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)',
  'linear-gradient(to top, #cfd9df 0%, #e2ebf0 100%)',
  'linear-gradient(to right, #fa709a 0%, #fee140 100%)',
  'linear-gradient(to top, #30cfd0 0%, #330867 100%)',
  'linear-gradient(to bottom, #000000 0%, #434343 100%)',
];

const DesignCustomizer: React.FC<Props> = ({ user }) => {
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const profileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const existing = db.getPageByUsername(user.username);
    if (existing) {
      setPage({
        ...existing,
        backgroundType: existing.backgroundType || 'color',
        backgroundColor: existing.backgroundColor || '#ffffff',
        backgroundGradient: existing.backgroundGradient || GRADIENTS[0],
      } as BioPage);
      setLinks(db.getLinks(existing.id).filter(l => l.isActive));
    } else {
      const newPage: BioPage = {
        id: Math.random().toString(36).substr(2, 9),
        userId: user.id,
        title: user.name,
        description: `Bem-vindo ao meu perfil!`,
        profileImageUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(user.name)}&background=random&size=200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true,
        backgroundType: 'color',
        backgroundColor: '#ffffff',
        backgroundGradient: GRADIENTS[0],
      };
      db.savePage(newPage);
      setPage(newPage);
      setLinks([]);
    }
  }, [user]);

  const updatePage = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  const handleProfileImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("A imagem deve ter no máximo 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        updatePage({ profileImageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleBgImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updatePage({ 
          backgroundImageUrl: reader.result as string,
          backgroundType: 'image'
        });
      };
      reader.readAsDataURL(file);
    }
  };

  if (!page) return null;

  const getBackgroundStyle = () => {
    if (page.backgroundType === 'color') return { backgroundColor: page.backgroundColor };
    if (page.backgroundType === 'gradient') return { backgroundImage: page.backgroundGradient };
    if (page.backgroundType === 'image') return { 
      backgroundImage: `url(${page.backgroundImageUrl})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center'
    };
    return { backgroundColor: '#ffffff' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
      <div className="space-y-8 pb-20">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Personalizar Design</h1>
          <p className="text-gray-500 font-medium">Deixe a página com a sua cara.</p>
        </div>

        {/* Informações Básicas e Foto */}
        <section className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 space-y-8">
          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <Camera size={16} /> Perfil e Foto
          </h3>

          <div className="flex flex-col md:flex-row items-center gap-8">
            <div className="relative group">
              <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-gray-50 shadow-xl group-hover:opacity-80 transition-all">
                <img src={page.profileImageUrl} className="w-full h-full object-cover" alt="Profile" />
              </div>
              <button 
                onClick={() => profileInputRef.current?.click()}
                className="absolute bottom-0 right-0 bg-blue-600 text-white p-2.5 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all"
              >
                <Upload size={14} />
              </button>
              <input type="file" ref={profileInputRef} className="hidden" accept="image/*" onChange={handleProfileImageUpload} />
            </div>

            <div className="flex-1 w-full space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Título da Página</label>
                <input 
                  className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none text-sm font-bold focus:ring-2 focus:ring-blue-500 transition-all"
                  value={page.title}
                  onChange={(e) => updatePage({ title: e.target.value })}
                  placeholder="Nome ou Título"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Descrição / Bio</label>
                <textarea 
                  className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none text-sm font-medium focus:ring-2 focus:ring-blue-500 transition-all h-20 resize-none"
                  value={page.description}
                  onChange={(e) => updatePage({ description: e.target.value })}
                  placeholder="Conte um pouco sobre você..."
                />
              </div>
            </div>
          </div>
        </section>

        {/* Background Selector */}
