import { User, BioPage, BioLink, Product } from '../types';

const STORAGE_KEYS = {
  USERS: 'biolink_users',
  PAGES: 'biolink_pages',
  LINKS: 'biolink_links',
  ANALYTICS: 'biolink_analytics',
  PRODUCTS: 'biolink_products'
};

export const db = {
  getUsers: (): User[] => JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]'),
  saveUser: (user: User) => {
    const users = db.getUsers();
    localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify([...users, user]));
  },
  findUserByUsername: (username: string) => db.getUsers().find(u => u.username === username),

  getPages: (): BioPage[] => JSON.parse(localStorage.getItem(STORAGE_KEYS.PAGES) || '[]'),
  getPageByUsername: (username: string) => {
    const user = db.findUserByUsername(username);
    if (!user) return null;
    return db.getPages().find(p => p.userId === user.id);
  },
  savePage: (page: BioPage) => {
    const pages = db.getPages().filter(p => p.id !== page.id);
    localStorage.setItem(STORAGE_KEYS.PAGES, JSON.stringify([...pages, page]));
  },

  getLinks: (pageId: string): BioLink[] => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]');
    return links.filter((l: BioLink) => l.bioPageId === pageId).sort((a: any, b: any) => a.position - b.position);
  },
  saveLink: (link: BioLink) => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]').filter((l: any) => l.id !== link.id);
    localStorage.setItem(STORAGE_KEYS.LINKS, JSON.stringify([...links, link]));
  },
  deleteLink: (id: string) => {
    const links = JSON.parse(localStorage.getItem(STORAGE_KEYS.LINKS) || '[]').filter((l: any) => l.id !== id);
    localStorage.setItem(STORAGE_KEYS.LINKS, JSON.stringify(links));
  },

  // Módulo de Produtos
  getProducts: (pageId: string): Product[] => {
    const products = JSON.parse(localStorage.getItem(STORAGE_KEYS.PRODUCTS) || '[]');
    return products.filter((p: Product) => p.bioPageId === pageId).sort((a: any, b: any) => a.position - b.position);
  },
  saveProduct: (product: Product) => {
    const products = JSON.parse(localStorage.getItem(STORAGE_KEYS.PRODUCTS) || '[]').filter((p: any) => p.id !== product.id);
    localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify([...products, product]));
  },
  deleteProduct: (id: string) => {
    const products = JSON.parse(localStorage.getItem(STORAGE_KEYS.PRODUCTS) || '[]').filter((p: any) => p.id !== id);
    localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(products));
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Product, BioPage } from '../types';
import { db } from '../services/db';
import { Plus, Trash2, ShoppingBag, X, Upload, Tag, MessageSquare, DollarSign } from 'lucide-react';

interface Props {
  user: User;
}

const CatalogManager: React.FC<Props> = ({ user }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [page, setPage] = useState<BioPage | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    price: '',
    promoPrice: '',
    imageUrl: ''
  });

  useEffect(() => {
    const p = db.getPageByUsername(user.username);
    if (p) {
      setPage(p);
      setProducts(db.getProducts(p.id));
    }
  }, [user]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, imageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (!page) return;

    const newProduct: Product = {
      id: `prod_${Date.now()}`,
      bioPageId: page.id,
      name: formData.name,
      description: formData.description,
      price: parseFloat(formData.price),
      promoPrice: formData.promoPrice ? parseFloat(formData.promoPrice) : undefined,
      imageUrl: formData.imageUrl || 'https://via.placeholder.com/300',
      isActive: true,
      position: products.length
    };

    db.saveProduct(newProduct);
    setProducts([...products, newProduct]);
    setIsAdding(false);
    setFormData({ name: '', description: '', price: '', promoPrice: '', imageUrl: '' });
  };

  const handleDelete = (id: string) => {
    if (confirm("Remover este produto do catálogo?")) {
      db.deleteProduct(id);
      setProducts(products.filter(p => p.id !== id));
    }
  };

  const updatePageConfig = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  if (!page) return null;

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-20 text-left">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Catálogo de Produtos</h1>
          <p className="text-sm text-gray-500 font-medium">Transforme sua bio em uma vitrine de vendas.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100"
        >
          <Plus size={20} /> Novo Produto
        </button>
      </div>

      {/* Configurações de Conversão */}
      <section className="bg-white p-8 rounded-[2rem] border border-gray-100 shadow-sm space-y-6">
        <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
          <MessageSquare size={16} /> Configurações de Venda
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">WhatsApp para Vendas</label>
            <input 
              className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold focus:ring-2 focus:ring-green-500"
              placeholder="Ex: 5511999998888"
              value={page.catalogWhatsApp || ''}
              onChange={(e) => updatePageConfig({ catalogWhatsApp: e.target.value })}
            />
          </div>
          <div>
            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Texto do Botão (CTA)</label>
            <input 
              className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold focus:ring-2 focus:ring-blue-500"
              placeholder="Ex: Comprar no WhatsApp"
              value={page.catalogCtaText || ''}
              onChange={(e) => updatePageConfig({ catalogCtaText: e.target.value })}
            />
          </div>
        </div>
        <div className="flex items-center gap-3 p-4 bg-blue-50 rounded-2xl border border-blue-100">
           <div className={`w-12 h-6 rounded-full relative transition-all cursor-pointer ${page.catalogEnabled ? 'bg-blue-600' : 'bg-gray-300'}`} onClick={() => updatePageConfig({ catalogEnabled: !page.catalogEnabled })}>
              <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${page.catalogEnabled ? 'left-7' : 'left-1'}`}></div>
           </div>
           <span className="text-sm font-bold text-blue-900">Exibir catálogo na página pública</span>
        </div>
      </section>

      {isAdding && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in duration-300 relative">
            <button onClick={() => setIsAdding(false)} className="absolute top-6 right-6 text-gray-400 hover:text-red-500"><X size={24} /></button>
            <h3 className="text-xl font-black mb-6">Adicionar Item</h3>
            <form onSubmit={handleSaveProduct} className="space-y-4">
              <div className="flex justify-center mb-4">
                <button 
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="w-32 h-32 rounded-3xl border-2 border-dashed border-gray-200 flex flex-col items-center justify-center overflow-hidden hover:border-blue-400 transition-all bg-gray-50"
                >
                  {formData.imageUrl ? (
                    <img src={formData.imageUrl} className="w-full h-full object-cover" />
                  ) : (
                    <><Upload size={24} className="text-gray-300 mb-1" /><span className="text-[10px] font-bold text-gray-400 uppercase">Foto</span></>
                  )}
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
              </div>
              <input 
                placeholder="Nome do Produto" 
                className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                required
              />
              <textarea 
                placeholder="Breve descrição" 
                className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-medium h-24 resize-none"
                value={formData.description}
                onChange={e => setFormData({...formData, description: e.target.value})}
              />
              <div className="grid grid-cols-2 gap-4">
                <div className="relative">
                  <DollarSign size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input 
                    type="number" step="0.01" placeholder="Preço" 
                    className="w-full pl-10 pr-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                    value={formData.price}
                    onChange={e => setFormData({...formData, price: e.target.value})}
                    required
                  />
                </div>
                <div className="relative">
                  <Tag size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                  <input 
                    type="number" step="0.01" placeholder="Promo (opc)" 
                    className="w-full pl-10 pr-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold text-green-600"
                    value={formData.promoPrice}
                    onChange={e => setFormData({...formData, promoPrice: e.target.value})}
                  />
                </div>
              </div>
              <button className="w-full py-5 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl mt-4">Salvar no Catálogo</button>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {products.map((product) => (
          <div key={product.id} className="bg-white p-4 rounded-[2rem] border border-gray-100 shadow-sm flex gap-4 group hover:shadow-md transition-all">
            <div className="w-24 h-24 rounded-2xl overflow-hidden bg-gray-50 border border-gray-100 flex-shrink-0">
              <img src={product.imageUrl} className="w-full h-full object-cover" />
            </div>
            <div className="flex-1 min-w-0 flex flex-col justify-center">
              <h4 className="font-bold text-gray-900 truncate">{product.name}</h4>
              <div className="flex items-center gap-2 mt-1">
                {product.promoPrice ? (
                  <>
                    <span className="text-green-600 font-black text-sm">R$ {product.promoPrice.toFixed(2)}</span>
                    <span className="text-gray-300 font-bold text-xs line-through">R$ {product.price.toFixed(2)}</span>
                  </>
                ) : (
                  <span className="text-gray-900 font-black text-sm">R$ {product.price.toFixed(2)}</span>
                )}
              </div>
            </div>
            <div className="flex items-center pr-2">
              <button 
                onClick={() => handleDelete(product.id)}
                className="p-3 text-gray-200 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              >
                <Trash2 size={18} />
              </button>
            </div>
          </div>
        ))}

        {products.length === 0 && !isAdding && (
          <div className="col-span-full py-16 text-center border-4 border-dashed border-gray-50 rounded-[3rem] bg-white">
            <ShoppingBag size={48} className="mx-auto text-gray-100 mb-4" />
            <p className="text-gray-300 font-black uppercase tracking-widest text-sm">Seu catálogo está vazio</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CatalogManager;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate, useParams } from 'react-router-dom';
import Login from './pages/Login';
import Register from './pages/Register';
import DashboardLayout from './components/DashboardLayout';
import DashboardHome from './pages/DashboardHome';
import LinksManager from './pages/LinksManager';
import DesignCustomizer from './pages/DesignCustomizer';
import CatalogManager from './pages/CatalogManager';
import Analytics from './pages/Analytics';
import PublicBio from './pages/PublicBio';
import { AuthState, User } from './types';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>(() => {
    const saved = localStorage.getItem('auth');
    return saved ? JSON.parse(saved) : { user: null, token: null, isAuthenticated: false };
  });

  useEffect(() => {
    localStorage.setItem('auth', JSON.stringify(auth));
  }, [auth]);

  const login = (user: User, token: string) => {
    setAuth({ user, token, isAuthenticated: true });
  };

  const logout = () => {
    setAuth({ user: null, token: null, isAuthenticated: false });
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={auth.isAuthenticated ? <Navigate to="/dashboard" /> : <Navigate to="/login" />} />

        <Route path="/login" element={<Login onLogin={login} />} />
        <Route path="/register" element={<Register onRegister={login} />} />

        <Route path="/dashboard" element={auth.isAuthenticated ? <DashboardLayout user={auth.user!} onLogout={logout} /> : <Navigate to="/login" />}>
          <Route index element={<DashboardHome user={auth.user!} />} />
          <Route path="links" element={<LinksManager user={auth.user!} />} />
          <Route path="design" element={<DesignCustomizer user={auth.user!} />} />
          <Route path="catalog" element={<CatalogManager user={auth.user!} />} />
          <Route path="analytics" element={<Analytics user={auth.user!} />} />
        </Route>

        <Route path="/:username" element={<PublicBio />} />

        <Route path="*" element={<div className="p-10 text-center">404 - Not Found</div>} />
      </Routes>
    </HashRouter>
  );
};

export default App;

