  const isDarkBackground = (page.backgroundType === 'color' && page.backgroundColor === '#000000') || (page.backgroundType === 'image');

  return (
    <div 
      className="min-h-screen flex flex-col items-center pt-16 pb-24 px-6 transition-all duration-700"
