import React, { useState, useEffect } from 'react';
import { User, BioLink, BioPage } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Plus, Trash2, GripVertical, ToggleLeft, ToggleRight, MessageCircle, X, Check } from 'lucide-react';

interface Props {
  user: User;
}

const LinksManager: React.FC<Props> = ({ user }) => {
  const [links, setLinks] = useState<BioLink[]>([]);
  const [newLinkTitle, setNewLinkTitle] = useState('');
  const [newLinkUrl, setNewLinkUrl] = useState('');
  const [whatsappPhone, setWhatsappPhone] = useState('');
  const [whatsappMessage, setWhatsappMessage] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [isWhatsappMode, setIsWhatsappMode] = useState(false);

  // Função para obter ou criar a página de forma segura
  const getOrCreatePage = (): BioPage => {
    let page = db.getPageByUsername(user.username);
    if (!page) {
      // Cria uma página padrão caso o usuário tenha ido direto para Links sem passar por Design
      // Fix: Add missing catalog properties to comply with BioPage interface
      const newPage: BioPage = {
        id: `page_${Math.random().toString(36).substr(2, 9)}`,
        userId: user.id,
        title: user.name,
        description: `Bem-vindo ao meu BioLink!`,
        profileImageUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(user.name)}&background=random&size=200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true,
        backgroundType: 'color',
        backgroundColor: '#ffffff',
        backgroundGradient: 'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)',
        catalogEnabled: false,
        catalogTitle: 'Meu Catálogo',
        catalogCtaText: 'Pedir via WhatsApp',
      };
      db.savePage(newPage);
      return newPage;
    }
    return page;
  };

  const loadLinks = () => {
    const page = db.getPageByUsername(user.username);
    if (page) {
      const storedLinks = db.getLinks(page.id);
      setLinks([...storedLinks]);
    }
  };

  useEffect(() => {
    loadLinks();
  }, [user.username]);

  const resetForm = () => {
    setNewLinkTitle('');
    setNewLinkUrl('');
    setWhatsappPhone('');
    setWhatsappMessage('');
    setIsAdding(false);
    setIsWhatsappMode(false);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // 1. Garante que a página existe antes de prosseguir
    const currentPage = getOrCreatePage();

    let finalUrl = '';
    let finalTitle = newLinkTitle.trim();

    if (isWhatsappMode) {
      const cleanPhone = whatsappPhone.replace(/\D/g, '');
      if (!cleanPhone || cleanPhone.length < 10) {
        alert("Digite um WhatsApp válido (ex: 11999998888)");
        return;
      }
      const encodedMsg = encodeURIComponent(whatsappMessage);
      finalUrl = `https://wa.me/${cleanPhone}${encodedMsg ? `?text=${encodedMsg}` : ''}`;
      if (!finalTitle) finalTitle = 'WhatsApp';
    } else {
      let urlInput = newLinkUrl.trim();
      if (!urlInput) {
        alert("A URL é obrigatória.");
        return;
      }
      if (!urlInput.startsWith('http')) {
        urlInput = `https://${urlInput}`;
      }
      finalUrl = urlInput;
      if (!finalTitle) finalTitle = 'Novo Link';
    }

    const newLinkObj: BioLink = {
      id: `link_${Date.now()}`,
      bioPageId: currentPage.id,
      title: finalTitle,
      url: finalUrl,
      position: links.length,
      clicks: 0,
      isActive: true,
    };

    try {
      db.saveLink(newLinkObj);
      setLinks(prev => [...prev, newLinkObj]);
      resetForm();
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar link.");
    }
  };

  const toggleLinkStatus = (id: string) => {
    const updated = links.map(l => {
      if (l.id === id) {
        const up = { ...l, isActive: !l.isActive };
        db.saveLink(up);
        return up;
      }
      return l;
    });
    setLinks(updated);
  };

  const handleDelete = (id: string) => {
    if (confirm("Excluir este botão?")) {
      db.deleteLink(id);
      setLinks(prev => prev.filter(l => l.id !== id));
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-6 pb-20 text-left">
      <div className="flex justify-between items-center mb-2">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Meus Links</h1>
          <p className="text-sm text-gray-400 font-medium">Gerencie os botões da sua página pública.</p>
        </div>
        {!isAdding && (
          <button 
            onClick={() => setIsAdding(true)}
            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100"
          >
            <Plus size={20} /> Novo Botão
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[2.5rem] shadow-2xl border border-gray-100 animate-in fade-in slide-in-from-top-2">
          <form onSubmit={handleSave} className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="font-black text-xl text-gray-800">Criar Novo</h3>
              <button type="button" onClick={resetForm} className="text-gray-400 hover:text-red-500">
                <X size={24} />
              </button>
            </div>

            <div className="flex p-1 bg-gray-100 rounded-2xl">
              <button 
                type="button"
                onClick={() => setIsWhatsappMode(false)}
                className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${!isWhatsappMode ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-400'}`}
              >
                Link Comum
              </button>
              <button 
                type="button"
                onClick={() => setIsWhatsappMode(true)}
                className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${isWhatsappMode ? 'bg-white text-green-600 shadow-sm' : 'text-gray-400'}`}
              >
                WhatsApp
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Título do Botão</label>
                <input 
                  type="text" 
                  autoFocus
                  placeholder="Ex: Meu Portfólio"
                  value={newLinkTitle}
                  onChange={e => setNewLinkTitle(e.target.value)}
                  className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {isWhatsappMode ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Número</label>
                    <input 
                      type="tel" 
                      placeholder="11999998888"
                      value={whatsappPhone}
                      onChange={e => setWhatsappPhone(e.target.value)}
                      className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">Mensagem</label>
                    <input 
                      type="text" 
                      placeholder="Olá!"
                      value={whatsappMessage}
                      onChange={e => setWhatsappMessage(e.target.value)}
                      className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                    />
                  </div>
                </div>
              ) : (
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">URL / Link</label>
                  <input 
                    type="text" 
                    placeholder="www.google.com"
                    value={newLinkUrl}
                    onChange={e => setNewLinkUrl(e.target.value)}
                    className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                  />
                </div>
              )}
            </div>

            <button 
              type="submit"
              className="w-full py-5 bg-gray-900 text-white rounded-2xl font-black text-sm uppercase tracking-[0.2em] shadow-xl hover:bg-black active:scale-[0.98] transition-all"
            >
              Confirmar e Salvar
            </button>
          </form>
        </div>
      )}

      <div className="space-y-4">
        {links.length > 0 ? (
          links.map((link) => (
            <div key={link.id} className="bg-white p-5 rounded-[2rem] border border-gray-100 flex items-center gap-4 group">
              <div className="text-gray-200"><GripVertical size={20} /></div>
              <div className="flex-1 min-w-0">
                <h4 className={`font-bold text-gray-900 truncate ${!link.isActive && 'opacity-40'}`}>{link.title}</h4>
                <p className="text-[10px] text-gray-400 font-bold truncate">{link.url}</p>
              </div>
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => toggleLinkStatus(link.id)}
                  className={`p-1 transition-all ${link.isActive ? 'text-blue-600' : 'text-gray-200'}`}
                >
                  {link.isActive ? <ToggleRight size={36} /> : <ToggleLeft size={36} />}
                </button>
                <button 
                  onClick={() => handleDelete(link.id)}
                  className="p-3 text-gray-200 hover:text-red-500 transition-colors"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))
        ) : (
          !isAdding && (
            <div className="py-20 text-center bg-white rounded-[3rem] border-2 border-dashed border-gray-100">
               <p className="font-bold text-gray-300 uppercase tracking-widest text-xs">Nenhum link criado</p>
            </div>
          )
        )}
      </div>
    </div>
  );
};

export default LinksManager;

import React, { useState, useEffect, useRef } from 'react';
import { User, BioPage, BioLink } from '../types';
import { db } from '../services/db';
import { THEMES, FONTS } from '../constants';
import { Check, Image as ImageIcon, Paintbrush, MoveRight, Upload, Camera } from 'lucide-react';

interface Props {
  user: User;
}

const GRADIENTS = [
  'linear-gradient(to bottom, #ff9a9e 0%, #fecfef 99%, #fecfef 100%)',
  'linear-gradient(120deg, #a1c4fd 0%, #c2e9fb 100%)',
  'linear-gradient(to top, #cfd9df 0%, #e2ebf0 100%)',
  'linear-gradient(to right, #fa709a 0%, #fee140 100%)',
  'linear-gradient(to top, #30cfd0 0%, #330867 100%)',
  'linear-gradient(to bottom, #000000 0%, #434343 100%)',
];

const DesignCustomizer: React.FC<Props> = ({ user }) => {
  const [page, setPage] = useState<BioPage | null>(null);
  const [links, setLinks] = useState<BioLink[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const profileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const existing = db.getPageByUsername(user.username);
    if (existing) {
      setPage({
        ...existing,
        backgroundType: existing.backgroundType || 'color',
        backgroundColor: existing.backgroundColor || '#ffffff',
        backgroundGradient: existing.backgroundGradient || GRADIENTS[0],
      } as BioPage);
      setLinks(db.getLinks(existing.id).filter(l => l.isActive));
    } else {
      // Fix: Add missing catalog properties to comply with BioPage interface
      const newPage: BioPage = {
        id: Math.random().toString(36).substr(2, 9),
        userId: user.id,
        title: user.name,
        description: `Bem-vindo ao meu perfil!`,
        profileImageUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(user.name)}&background=random&size=200`,
        themeColor: THEMES[0].color,
        fontFamily: FONTS[0].family,
        isActive: true,
        backgroundType: 'color',
        backgroundColor: '#ffffff',
        backgroundGradient: GRADIENTS[0],
        catalogEnabled: false,
        catalogTitle: 'Meu Catálogo',
        catalogCtaText: 'Pedir via WhatsApp',
      };
      db.savePage(newPage);
      setPage(newPage);
      setLinks([]);
    }
  }, [user]);

  const updatePage = (updates: Partial<BioPage>) => {
    if (!page) return;
    const updated = { ...page, ...updates };
    setPage(updated);
    db.savePage(updated);
  };

  const handleProfileImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024 * 2) {
        alert("A imagem deve ter no máximo 2MB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        updatePage({ profileImageUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleBgImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        updatePage({ 
          backgroundImageUrl: reader.result as string,
          backgroundType: 'image'
        });
      };
      reader.readAsDataURL(file);
    }
  };

  if (!page) return null;

  const getBackgroundStyle = () => {
    if (page.backgroundType === 'color') return { backgroundColor: page.backgroundColor };
    if (page.backgroundType === 'gradient') return { backgroundImage: page.backgroundGradient };
    if (page.backgroundType === 'image') return { 
      backgroundImage: `url(${page.backgroundImageUrl})`,
      backgroundSize: 'cover',
      backgroundPosition: 'center'
    };
    return { backgroundColor: '#ffffff' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
      <div className="space-y-8 pb-20 text-left">
        <div>
          <h1 className="text-2xl font-black text-gray-900">Personalizar Design</h1>
          <p className="text-gray-500 font-medium">Deixe a página com a sua cara.</p>
        </div>

        {/* Informações Básicas e Foto */}
        <section className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 space-y-8">
          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
            <Camera size={16} /> Perfil e Foto
          </h3>

          <div className="flex flex-col md:flex-row items-center gap-8">
            <div className="relative group">
              <div className="w-24 h-24 rounded-full overflow-hidden border-4 border-gray-50 shadow-xl group-hover:opacity-80 transition-all">
                <img src={page.profileImageUrl} className="w-full h-full object-cover" alt="Profile" />
              </div>
              <button 
                onClick={() => profileInputRef.current?.click()}
                className="absolute bottom-0 right-0 bg-blue-600 text-white p-2.5 rounded-full shadow-xl hover:scale-110 active:scale-95 transition-all"
              >
                <Upload size={14} />
              </button>
              <input type="file" ref={profileInputRef} className="hidden" accept="image/*" onChange={handleProfileImageUpload} />
            </div>

            <div className="flex-1 w-full space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Título da Página</label>
                <input 
                  className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none text-sm font-bold focus:ring-2 focus:ring-blue-500 transition-all"
                  value={page.title}
                  onChange={(e) => updatePage({ title: e.target.value })}
                  placeholder="Nome ou Título"
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2 ml-1">Descrição / Bio</label>
                <textarea 
                  className="w-full px-6 py-3.5 bg-gray-50 border border-gray-100 rounded-2xl outline-none text-sm font-medium focus:ring-2 focus:ring-blue-500 transition-all h-20 resize-none"
                  value={page.description}
                  onChange={(e) => updatePage({ description: e.target.value })}
                  placeholder="Conte um pouco sobre você..."
                />
              </div>
            </div>
          </div>
        </section>

        {/* Background Selector */}
        <section className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 space-y-6">
          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Fundo da Página</h3>

          <div className="flex bg-gray-100 p-1.5 rounded-2xl">
            {(['color', 'gradient', 'image'] as const).map((type) => (
              <button
                key={type}
                onClick={() => updatePage({ backgroundType: type })}
                className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${
                  page.backgroundType === type ? 'bg-white shadow-md text-blue-600' : 'text-gray-400 hover:text-gray-600'
                }`}
              >
                {type === 'color' ? 'Cor Sólida' : type === 'gradient' ? 'Gradiente' : 'Imagem'}
              </button>
            ))}
          </div>

          <div className="pt-2">
            {page.backgroundType === 'color' && (
              <div className="grid grid-cols-6 gap-3">
                {['#ffffff', '#f8fafc', '#000000', '#ef4444', '#3b82f6', '#10b981', '#f59e0b', '#8b5cf6'].map(color => (
                  <button
                    key={color}
                    onClick={() => updatePage({ backgroundColor: color })}
                    className="aspect-square rounded-2xl border-2 border-gray-50 shadow-sm flex items-center justify-center transition-transform hover:scale-110"
                    style={{ backgroundColor: color }}
                  >
                    {page.backgroundColor === color && <Check size={16} className={color === '#ffffff' ? 'text-black' : 'text-white'} />}
                  </button>
                ))}
              </div>
            )}

            {page.backgroundType === 'gradient' && (
              <div className="grid grid-cols-3 gap-4">
                {GRADIENTS.map((grad, i) => (
                  <button
                    key={i}
                    onClick={() => updatePage({ backgroundGradient: grad })}
                    className="h-16 rounded-2xl border-2 border-gray-50 shadow-sm transition-transform hover:scale-105 overflow-hidden"
                    style={{ backgroundImage: grad }}
                  >
                    {page.backgroundGradient === grad && <Check size={16} className="text-white mx-auto drop-shadow-md" />}
                  </button>
                ))}
              </div>
            )}

            {page.backgroundType === 'image' && (
              <div className="space-y-4">
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-10 border-4 border-dashed border-gray-50 rounded-[2rem] flex flex-col items-center justify-center text-gray-300 hover:border-blue-200 hover:text-blue-400 transition-all bg-gray-50/50"
                >
                  {page.backgroundImageUrl ? (
                    <div className="relative">
                      <img src={page.backgroundImageUrl} className="h-24 w-40 object-cover rounded-2xl mb-3 shadow-xl" />
                      <div className="absolute inset-0 flex items-center justify-center bg-black/20 rounded-2xl opacity-0 hover:opacity-100 transition-opacity">
                        <Upload className="text-white" size={24} />
                      </div>
                    </div>
                  ) : (
                    <>
                      <Upload size={32} className="mb-3" />
                      <span className="text-xs font-black uppercase tracking-widest">Subir Imagem de Fundo</span>
                    </>
                  )}
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleBgImageUpload} />
              </div>
            )}
          </div>
        </section>

        {/* Estilo dos Botões */}
        <section className="bg-white p-8 rounded-[2rem] shadow-sm border border-gray-100 space-y-6">
          <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest">Cor dos Botões</h3>
          <div className="grid grid-cols-5 gap-4">
            {THEMES.map(theme => (
              <button 
                key={theme.id}
                onClick={() => updatePage({ themeColor: theme.color })}
