    if (email === 'admin@teste.com' && !user) {
        user = {
            id: 'admin-id',
            name: 'Usuário Teste',
            email: 'admin@teste.com',
            username: 'admin',
            createdAt: new Date().toISOString()
        };
        db.saveUser(user);
