              <form onSubmit={handleRecovery} className="space-y-4">
                <div>
                  <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 ml-1">E-mail Cadastrado</label>
                  <input 
                    type="email" 
                    required
                    className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl outline-none font-bold"
                    value={recoveryEmail}
                    onChange={e => setRecoveryEmail(e.target.value)}
