  const [copied, setCopied] = useState(false);

  const userPassword = (user as any).passwordHash || 'N/A';

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('loading');
    setErrorMessage('');

    const users = db.getUsers();

    const usernameExists = users.find(u => u.username === formData.username && u.id !== user.id);
    if (usernameExists) {
      setStatus('error');
      setErrorMessage('Este nome de usuário já está sendo usado por outra pessoa.');
      return;
    }

    const updatedUser: User = {
      ...user,
      name: formData.name,
      email: formData.email,
      username: formData.username.toLowerCase().replace(/[^a-z0-9_]/g, ''),
    };

    const otherUsers = users.filter(u => u.id !== user.id);
    localStorage.setItem('biolink_users', JSON.stringify([...otherUsers, updatedUser]));

    onUpdateUser(updatedUser);

    setStatus('success');
    setTimeout(() => setStatus('idle'), 3000);
  };

